arguments.command:
ed -s /src/libxml2/parser.c <<'ED'
/buf[len] = 0;/i
    if (len + 1 >= size) {
        xmlChar *new_buf;
        size_t new_size = size * 2;
        new_buf = (xmlChar *) xmlRealloc(buf, new_size);
        if (new_buf == NULL) {
            xmlFree (buf);
            xmlErrMemory(ctxt, NULL);
            return;
        }
        buf = new_buf;
        size = new_size;
    }
.
wq
ED
